CREATE OR REPLACE FUNCTION public.activate_member_trial(p_code_hash text DEFAULT NULL::text)
 RETURNS TABLE(duration_months integer, trial_ends_at timestamp with time zone, offer_applied boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_user uuid := auth.uid();
 v_auth_created timestamptz;
 v_phone_confirmed timestamptz;
 v_promo public.promo_codes%rowtype;
 v_months integer := 3;
 v_end timestamptz;
 v_start timestamptz;
 v_existing public.member_trials%rowtype;
begin
 if v_user is null then raise exception 'Sign in to activate your trial'; end if;
 select created_at,phone_confirmed_at into v_auth_created,v_phone_confirmed from auth.users where id=v_user;
 if v_phone_confirmed is null then raise exception 'Verify your mobile number first'; end if;
 perform pg_advisory_xact_lock(hashtextextended(v_user::text,0));
 select * into v_existing from public.member_trials where user_id=v_user;
 if found then
   return query select v_existing.duration_months,v_existing.ends_at,(v_existing.promo_code_id is not null);
   return;
 end if;
 if p_code_hash is not null then
   if p_code_hash !~ '^[a-f0-9]{64}$' then raise exception 'Invalid invitation code'; end if;
   select * into v_promo from public.promo_codes where code_hash=p_code_hash for update;
   if not found or not v_promo.is_active or v_promo.starts_at>now()
      or (v_promo.expires_at is not null and v_promo.expires_at<now())
      or v_promo.redemption_count>=v_promo.max_redemptions then
      raise exception 'Invitation code is invalid, expired or fully redeemed';
   end if;
   v_months:=v_promo.duration_months;
 end if;
 v_start:=v_auth_created;
 v_end:=v_start+make_interval(months=>v_months);
 insert into public.member_trials(user_id,starts_at,ends_at,duration_months,promo_code_id)
 values(v_user,v_start,v_end,v_months,case when p_code_hash is null then null else v_promo.id end);
 if p_code_hash is not null then
   insert into public.promo_redemptions(promo_code_id,user_id,trial_ends_at) values(v_promo.id,v_user,v_end);
   update public.promo_codes set redemption_count=redemption_count+1 where id=v_promo.id;
 end if;
 return query select v_months,v_end,(p_code_hash is not null);
end $function$
